288	    if (!explicit_override.empty()) return explicit_override; // Forscher-Override gewinnt
289	    // Primaer aus merge (die mechanische Wahrheit): Stufe1 = self-contained = full; Stufe2/3 = Teilmenge = abstract.
290	    if (merge == "Stufe1_CeOnly") return "full";
291	    if (merge == "Stufe2_PrueflingReplace") return "abstract";
292	    if (merge == "Stufe3_FullJoin") return "abstract";
293	    // Fallback wenn merge leer/unbekannt: aus der Reihen-id (A=full, B/C=abstract) — kongruent zur merge-Map.
294	    if (series_id == "A") return "full";
295	    if (series_id == "B" || series_id == "C") return "abstract";
296	    return "-"; // weder ableitbar noch gesetzt (kein Phantom-Typ)
