321	/// build_sota_passes(profile) — die Liste der SOTA-Reihen-Pässe AUS DEM PROFIL (1 Eintrag je real baubarem
322	/// <sota_series>). Reihenfolge = Profil-Reihenfolge (stabil/resumierbar). Ein nicht baubares (Reihe,Lebewesen)-
323	/// Paar (sota_module_for == nullopt) wird ausgelassen (ehrlich: kein Phantom-Pass). KEINE Selektion — das
324	/// Profil bestimmt, WELCHE Reihen/Lebewesen laufen.
325	[[nodiscard]] inline std::vector<SotaPass> build_sota_passes(cx::ThesisProfile const& tp) {
326	    std::vector<SotaPass> out;
327	    out.reserve(tp.sota_series.size());
328	    // ── M-CE-10 (Voll-Review 2026-07-13; per-Host-Auffächerung 2026-07-14) — SEMANTIK-ENTSCHEIDUNG ─────────────
329	    //   FRÜHER (2026-07-13) war Stufe2_PrueflingReplace KONZEPTIONELL EINE Binary (der HOT-Pilot): sota_module_for
330	    //   bildete die binary_id OHNE das angefragte lebewesen, mehrere <sota_series merge="Stufe2_.."> mit
331	    //   VERSCHIEDENEN lebewesen materialisierten DIESELBE Messung → Dedup kollabierte sie zu 1 Pass. Der damalige
332	    //   Anti-Phantom-Vorbehalt ("lebewesen in die binary_id zu ziehen = N FAKE-distinkte-ids für byte-identischen
333	    //   HOT-Code") galt, WEIL nur der HOT-Host existierte. JETZT (F/G-relevant, Ledger :1134) faechert Stufe2 je
334	    //   SOTA-Host eine EIGENE reale <Host>PrtStufe2ReplaceComposition (prt_art_merge_reference.hpp) — die binary_ids
335	    //   sind damit GENUINE per-Host distinkt (verschiedene Hosts = verschiedene Kompositionen, KEIN Fake-id), genau
336	    //   wie Stufe3. Die Mechanik bleibt:
337	    //     (a) DEDUP der Pässe auf (view_binary_id, fairness_mode): kollabiert nur noch WIRKLICH identische Messungen
338	    //         (gleicher Host + gleicher fairness_mode). Die LEGITIMEN fairness-Varianten (gleiche binary_id,
339	    //         verschiedener fairness_mode — DATEN-gated #156-Pinnung) bleiben getrennt; per-Host-St2 sind distinkt.
340	    //     (c) H2-ATTRIBUTION host-dominant: der Pass trägt den H2-Score seines HOST-Lebewesens (m->host_lebewesen);
341	    //         nach der Auffächerung ist der Host == das angefragte lebewesen (konsistent zu St1/St3).
342	    //   (b) Der Zähler res.sota_binary_ids zählt im Treiber (profile_run_entry) weiterhin DISTINKTE binary_ids.
343	    // ──────────────────────────────────────────────────────────────────────────────────────────────────────────
344	    std::set<std::pair<std::string, std::string>> seen_pass; // Dedup-Schlüssel: (view_binary_id, fairness_mode)
345	    for (auto const& s : tp.sota_series) {
346	        auto const m = sota_module_for(s.merge, s.lebewesen); // #178: dispatch auf die Stufe (merge)
347	        if (!m) continue;                                     // nicht baubares Paar (ehrlich: kein Phantom-Pass)
348	        std::string const reihe    = stufe_to_reihe(s.merge); // #178: Reihen-Tag mechanisch aus der Stufe
349	        std::string const view_bid = sota_view_binary_id(m->binary_id);
350	        std::string const fair     = s.fairness.empty() ? std::string{"-"} : s.fairness; // GO-5 Fork 6
351	        if (!seen_pass.emplace(view_bid, fair).second) continue; // M-CE-10 (a): identische Messung ⇒ genau 1 Pass
352	        out.push_back(SotaPass{reihe, s.lebewesen, m->binary_id, view_bid,
353	                               derive_pruefling_type(reihe, s.merge, s.pruefling_type), // #171: full/abstract
354	                               fair,
355	                               m->host_lebewesen}); // M-CE-10 (c): H2 host-dominant (St2 ⇒ "hot", nie das angefragte)
356	    }
357	    return out;
358	}
