103	// (1)+(2) PER-HOST-DISTINKT + HOST-DOMINANTE H2-ATTRIBUTION (host == lebewesen) — der Kern der M-CE-10-per-Host-
104	// Auffächerung über ein synthetisches Profil mit 3 verschiedenen St2-Lebewesen (art/masstree/surf).
105	TEST(SotaSt2Dedup, MultipleSt2DeclarationsArePerHostDistinctWithOwnHostH2) {
106	    auto const tp = parse_temp("  <sota_series_set>\n"
107	                               "    <sota_series id=\"A\" lebewesen=\"art\"      merge=\"Stufe2_PrueflingReplace\"/>\n"
108	                               "    <sota_series id=\"A\" lebewesen=\"masstree\" merge=\"Stufe2_PrueflingReplace\"/>\n"
109	                               "    <sota_series id=\"A\" lebewesen=\"surf\"     merge=\"Stufe2_PrueflingReplace\"/>\n"
110	                               "  </sota_series_set>\n");
111	    ASSERT_TRUE(tp.has_value());
112	    ASSERT_EQ(tp->sota_series.size(), 3u) << "3 St2-Deklarationen im Fixture";
113	
114	    std::vector<tlz::SotaPass> const passes = tlz::build_sota_passes(*tp);
115	    ASSERT_EQ(passes.size(), 3u) << "M-CE-10 per-Host: 3 verschiedene St2-Lebewesen = 3 distinkte Pässe";
116	    EXPECT_EQ(distinct_view_binary_ids(passes), 3u) << "jeder Host trägt eine DISTINKTE view_binary_id";
117	    for (auto const& p : passes) {
118	        EXPECT_TRUE(is_st2(p)) << p.view_binary_id;
119	        EXPECT_EQ(p.series, "A");
120	        EXPECT_EQ(p.pruefling_type, "abstract");
121	        // host-dominant: der Host IST das angefragte lebewesen (kein FIX "hot" mehr).
122	        EXPECT_EQ(p.h2_lebewesen, p.lebewesen) << "St2 trägt seinen eigenen Host (host == lebewesen)";
123	    }
124	
125	    // Über die committete Akte aufgelöst: der art-Pass trägt den ART-Score, NICHT den HOT-Score (der M-CE-10-Bug).
126	    auto const akte = tlz::parse_h2_score_akte(akte_path());
127	    ASSERT_TRUE(akte.has_value());
128	    tlz::H2CodeQualityEntry const* hot = akte->entry("hot");
129	    tlz::H2CodeQualityEntry const* art = akte->entry("art");
130	    ASSERT_NE(hot, nullptr);
131	    ASSERT_NE(art, nullptr);
132	    ASSERT_NE(hot->score, art->score) << "Fixture-Voraussetzung: hot- und art-Score unterscheiden sich";
133	    tlz::SotaPass const* art_pass = find_st2_for_host(passes, "art");
134	    ASSERT_NE(art_pass, nullptr) << "der art-St2-Pass existiert (per-Host)";
135	    EXPECT_EQ(tlz::h2_score_for(*akte, art_pass->h2_lebewesen), art->score) << "art-St2-Score == ART-Host-Score";
136	    EXPECT_NE(tlz::h2_score_for(*akte, art_pass->h2_lebewesen), hot->score)
137	        << "der art-St2-Pass darf NIE den HOT-Score tragen (die M-CE-10-Fehl-Attribution ist behoben)";
138	}
