140	// (3) DISTINKT-ZÄHLUNG am gepinnten m3v2_study (7 St1 + 7 St2 + 7 St3): 19 Pässe / 19 distinkte view_binary_ids.
141	TEST(SotaSt2Dedup, M3v2StudyYieldsNineteenDistinctSotaBinaries) {
142	    auto const tp = tlz::load_thesis_profile(m3v2_profile_path());
143	    ASSERT_TRUE(tp.has_value()) << "m3v2_study nicht lesbar (TABU-Wache): " << m3v2_profile_path().string();
144	
145	    std::vector<tlz::SotaPass> const passes = tlz::build_sota_passes(*tp);
146	    // 7 St1 (prt_art + 6 SOTA isoliert) + 6 St2 (per-Host; prt_art degeneriert = nullopt) + 6 St3 (prt_art
147	    // degeneriert = nullopt) = 19 distinkte reale Kompositionen (M-CE-10 per-Host: vor der Auffächerung 14).
148	    EXPECT_EQ(passes.size(), 19u) << "M-CE-10 per-Host: 7 St1 + 6 St2 + 6 St3 = 19 Pässe";
149	    EXPECT_EQ(distinct_view_binary_ids(passes), 19u) << "jeder Pass trägt eine DISTINKTE view_binary_id";
150	    EXPECT_EQ(passes.size(), distinct_view_binary_ids(passes))
151	        << "kein Pass dupliziert die Messung eines anderen (== res.sota_binary_ids-Semantik im Treiber)";
152	
153	    // GENAU 6 St2-Pässe (art/hot/masstree/surf/start/wormhole), je host-dominant auf DEN EIGENEN Host attribuiert.
154	    std::set<std::string> st2_hosts;
155	    for (auto const& p : passes)
156	        if (is_st2(p)) {
157	            st2_hosts.insert(p.h2_lebewesen);
158	            EXPECT_EQ(p.h2_lebewesen, p.lebewesen) << "jeder St2-Pass trägt seinen eigenen Host-Score";
159	            EXPECT_EQ(p.pruefling_type, "abstract");
160	            EXPECT_NE(p.h2_lebewesen, "prt_art") << "prt_art-Host ist in St2 degeneriert (nullopt)";
161	        }
162	    EXPECT_EQ(st2_hosts.size(), 6u) << "die 7 St2-Deklarationen ergeben 6 reale per-Host-Pässe (prt_art degeneriert)";
163	}
