166	// bleiben getrennte Pässe. Sonst würde der Dedup die dokumentierte #156-Pinnungs-Semantik zerstören.
167	TEST(SotaSt2Dedup, FairnessVariantsAreNotCollapsedBySameBinaryId) {
168	    auto const tp = parse_temp(
169	        "  <sota_series_set>\n"
170	        "    <sota_series id=\"A\" lebewesen=\"hot\" merge=\"Stufe1_CeOnly\" fairness=\"common_denominator\"/>\n"
171	        "    <sota_series id=\"A\" lebewesen=\"hot\" merge=\"Stufe1_CeOnly\" fairness=\"native\"/>\n"
172	        "  </sota_series_set>\n");
173	    ASSERT_TRUE(tp.has_value());
174	
175	    std::vector<tlz::SotaPass> const passes = tlz::build_sota_passes(*tp);
176	    ASSERT_EQ(passes.size(), 2u) << "gleiche binary_id, aber verschiedener fairness_mode ⇒ 2 Pässe (nicht dedupt)";
177	    EXPECT_EQ(passes[0].view_binary_id, passes[1].view_binary_id) << "beide teilen HEUTE dieselbe view-binary_id";
178	    EXPECT_NE(passes[0].fairness_mode, passes[1].fairness_mode);
179	    EXPECT_EQ(passes[0].fairness_mode, "common_denominator");
180	    EXPECT_EQ(passes[1].fairness_mode, "native");
181	    // Distinkte view_binary_ids == 1 (EINE reale DLL) — genau das zählt res.sota_binary_ids im Treiber, obwohl
182	    // 2 Pässe laufen (die Trennung lebt im fairness_mode-Tag + Resume-Stamp, nicht in der DLL).
183	    EXPECT_EQ(distinct_view_binary_ids(passes), 1u);
184	}
